{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "What is the objective of the plan — is it to minimize the total cost (purchases plus all repair costs) over the 10 stages?"
  ],
  "rationale": "The response contains a single clarification question asking for confirmation of the optimization objective."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "When a tool is sent for slow repair at the end of stage j, is it unavailable for the entire stage j+1 (i.e., it does not count toward r_{j+1}), and only counts toward availability starting at stage j+p?"
  ],
  "rationale": "The response asks for a single policy confirmation regarding the availability timeline of a tool during slow repair, which constitutes one semantically independent question."
}

{
  "action": "question",
  "question_count": 2,
  "is_atomic": false,
  "atomic_questions": [
    "For fast repair, if a tool is sent for fast repair at the end of stage j, does it become available at the start of stage j+q (so with q=1 it is back for stage j+1)?",
    "Is it unavailable during any stage in between?"
  ],
  "rationale": "The response asks two distinct things: the specific timing of availability (at the start of stage j+q) and the status during the intervening stages (unavailable). These are separate policy details that could theoretically be answered independently."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Can a tool be sent for repair at the end of a stage even if it is not needed to meet the requirement in that stage (i.e., is repair a free choice on any available tool, or only on tools that are actually broken)?"
  ],
  "rationale": "The response contains a single clarification question asking for a specific policy choice regarding when repairs are permitted."
}

{
  "action": "question",
  "question_count": 2,
  "is_atomic": false,
  "atomic_questions": [
    "When a tool is sent for repair at the end of stage j, is the choice between slow and fast repair made per tool at that moment?",
    "Can you split a group of tools (some slow, some fast) in the same stage?"
  ],
  "rationale": "The response contains two distinct inquiries: one regarding the timing and granularity of the repair choice (per tool vs. group), and another regarding the feasibility of splitting a group into different repair types. These can be answered independently."
}

